window.products.push({"id":830672,"name":"Biddeford 100-Inch x 90-Inch Heated Comfort Knit/Sherpa Blanket, King, Cloud Blue","category":"homeandappliances","retail price":0.0,"sale price":null,"image":"https://m.media-amazon.com/images/I/81kWDaNTAGL._AC_SL1500_.jpg","description":"This Heated Comfort Knit with Natural Sherpa Blanket is 100% Polyester and comes in Twin, Full, Queen and King sizes and decorative colors Cloud Blue, Sage, Fawn and Natural. It is Luxuriously cozy and provides therapeutic warmth, with an ultra thin wire for added comfort. Also has digital control(s) with Ten heat settings and a 10 hour auto shut-off for added safety. Dual temperature control is available for Queen and King sizes. For ease, this heated Blanket is machine washable, with an extra long 13 foot cord. Skip the winter cold, warm up with your heated Blanket and enjoy the energy savings as well.","images":["https://m.media-amazon.com/images/I/81kWDaNTAGL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/61zNIJh6ZCL._SL1500_.jpg","https://m.media-amazon.com/images/I/61TWUez1VxL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/51TIpnkrEpL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/51I6jTu8yCL._AC_SL1300_.jpg","https://m.media-amazon.com/images/I/31o9GyU6jnL._AC_.jpg"],"specifications":{"brand":"Biddeford Blankets","source_asin":"B084261X6J","category_path":"Home & Kitchen"},"sku":"BM-830672","productType":"Home & Appliances","inventory":0,"age_group":"Adult","gender":"Unisex","source_url":"https://www.amazon.com/dp/B084261X6J","source_catalog":"Amazon Reviews 2023 product metadata","source_file":"meta_Home_and_Kitchen_2023.jsonl","source_asin":"B084261X6J","price_pending":true,"merchant_ready":false});
