window.products.push({"id":830912,"name":"Hampton Nautical Rustic Red Whitewashed Cast Anchor with Nautical Rope Bottle Opener 5\" - Vintage Cast Iron Decor","category":"homeandappliances","retail price":10.4,"sale price":null,"image":"https://m.media-amazon.com/images/I/61YS6m4qsHL._AC_SL1280_.jpg","description":"This Rustic Red Whitewashed Cast Iron Anchor with Rope Bottle Opener 5\" is the perfect addition to any nautical themed kitchen. Both decorative and reliable, this rustic cast iron bottle opener will open even the most difficult of bottles with ease. This fully functional bottle opener also allows for easy decorative mounting and can be a great gift for the true nautical enthusiast in your life. This whitewashed cast iron bottle opener is perfect for all settings- on the beach, at a picnic or bbq, while tailgating, or wherever you need to quench your thirst.","images":["https://m.media-amazon.com/images/I/61YS6m4qsHL._AC_SL1280_.jpg","https://m.media-amazon.com/images/I/61zNIJh6ZCL._SL1500_.jpg","https://m.media-amazon.com/images/I/61TWUez1VxL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/51TIpnkrEpL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/51I6jTu8yCL._AC_SL1300_.jpg","https://m.media-amazon.com/images/I/31o9GyU6jnL._AC_.jpg"],"specifications":{"brand":"Hampton Nautical","source_asin":"B07H3JVDYX","category_path":"Home & Kitchen"},"sku":"BM-830912","productType":"Home & Appliances","inventory":0,"age_group":"Adult","gender":"Unisex","source_url":"https://www.amazon.com/dp/B07H3JVDYX","source_catalog":"Amazon Reviews 2023 product metadata","source_file":"meta_Home_and_Kitchen_2023.jsonl","source_asin":"B07H3JVDYX","price_pending":true,"merchant_ready":false});
